import type { CSSProperties, ReactNode } from "react";
import { BookOpen, Briefcase, Building, ChartLine, Globe, Mountain, Sigma, TrendingUp, type LucideIcon } from "lucide-react";
import type { CategoryId, SceneName } from "@/content/types";
import { cn } from "@/lib/cn";

/**
 * Graphic covers used instead of photography: a panel in the logo's blues (or a
 * light ice / cream variant) with a topographic contour-line pattern. The lines
 * are static SVGs in public/patterns (generated by `npm run patterns`) applied
 * as a CSS mask, so their colour comes from here.
 */
const VARIANTS: Record<SceneName, { background: string; line: string; opacity: number; ink: "light" | "dark" }> = {
  alps: { background: "linear-gradient(135deg, #114779 0%, #0d3861 100%)", line: "#faf0e6", opacity: 0.2, ink: "light" },
  summit: { background: "linear-gradient(160deg, #0d3861 0%, #0a2c4c 100%)", line: "#faf0e6", opacity: 0.18, ink: "light" },
  nyc: { background: "linear-gradient(135deg, #1d5790 0%, #0d3861 100%)", line: "#faf0e6", opacity: 0.18, ink: "light" },
  london: { background: "linear-gradient(135deg, #1d70b0 0%, #114779 100%)", line: "#faf0e6", opacity: 0.2, ink: "light" },
  trail: { background: "linear-gradient(135deg, #e4f1f8 0%, #c9e2ef 100%)", line: "#114779", opacity: 0.22, ink: "dark" },
  lake: { background: "linear-gradient(135deg, #eef6fb 0%, #d6e9f4 100%)", line: "#1d70b0", opacity: 0.24, ink: "dark" },
  campus: { background: "linear-gradient(135deg, #f7f4ee 0%, #ebe3d3 100%)", line: "#114779", opacity: 0.16, ink: "dark" },
};

/** Whether text and icons on this cover should be light (on blue) or dark (on ice / cream). */
export function coverInk(name: SceneName) {
  return VARIANTS[name].ink;
}

export const CATEGORY_ICONS: Record<CategoryId, LucideIcon> = {
  foundations: BookOpen,
  "corporate-finance": Building,
  valuation: ChartLine,
  "ib-ma": Briefcase,
  markets: TrendingUp,
  macro: Globe,
  "pe-hf": Mountain,
  quant: Sigma,
};

export function Cover({ name, className, title, children }: { name: SceneName; className?: string; title?: string; children?: ReactNode }) {
  const v = VARIANTS[name];
  const mask = `url(/patterns/${name}.svg)`;
  const lines: CSSProperties = {
    backgroundColor: v.line,
    opacity: v.opacity,
    maskImage: mask,
    WebkitMaskImage: mask,
    maskSize: "cover",
    WebkitMaskSize: "cover",
    maskPosition: "center",
    WebkitMaskPosition: "center",
    maskRepeat: "no-repeat",
    WebkitMaskRepeat: "no-repeat",
  };
  return (
    <div
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      className={cn("relative overflow-hidden", className)}
      style={{ background: v.background }}
    >
      <div className="absolute inset-0" style={lines} />
      {children && <div className="relative h-full">{children}</div>}
    </div>
  );
}

/** A small hand-drawn arrow that pairs with handwritten annotations. */
export function HandArrow({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 120 60" className={className} fill="none" aria-hidden>
      <path d="M6 10 C 30 50, 70 54, 108 36" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" />
      <path d="M96 28 L109 36 L97 46" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}
